theorem readStage_mem {delta : ℝ} (hd : 0 < delta) (n : ℕ) (e : ℚ)
    (q : ℕ) (om N : ℝ) (h : List ℕ) (s : Stage) {a : ℝ}
    (ha : readStage delta n e q om N h s = some a) : a ∈ levels n e q

theorem atRank_mem {delta : ℝ} (hd : 0 < delta) (n : ℕ) (e : ℚ)
    (q : ℕ) (om N : ℝ) (h : List ℕ) (r : ℕ) {a : ℝ}
    (ha : atRank r (readStage delta n e q om N h) = some a) : a ∈ levels n e q

theorem read_tag {delta : ℝ} (hdelta : 0 < delta) {n : ℕ} {d : OriginalData} {N x y : ℕ}
    (ht : tag delta hdelta n d N x=tag delta hdelta n d N y) :
    reads delta hdelta n d N x=reads delta hdelta n d N y ∧ historicalTag d N x=historicalTag d N y

